/*
 * prog25_balanced_multitype
 *
 * The original binary checks whether the first command‑line argument
 * contains a correctly balanced sequence of the three bracket types
 *   ( )   [ ]   { }
 * and prints either "BALANCED" or "UNBALANCED".
 *
 * If no argument is supplied the program treats the empty string as
 * balanced and prints "BALANCED".
 *
 * All other characters are ignored.
 */

#include <stdio.h>
#include <string.h>

int main(int argc, char **argv)
{
    /* No argument → empty string is considered balanced */
    if (argc < 2) {
        puts("BALANCED");
        return 0;
    }

    const char *s = argv[1];
    /* Simple stack for opening brackets – 1024 is more than enough for
       typical test inputs and matches the original program’s fixed‑size
       stack. */
    char stack[1024];
    int sp = 0;                     /* stack pointer */

    for (size_t i = 0; s[i] != '\0'; ++i) {
        char c = s[i];

        /* Opening brackets – push onto the stack */
        if (c == '(' || c == '[' || c == '{') {
            if (sp >= (int)sizeof(stack)) {   /* overflow – treat as unbalanced */
                puts("UNBALANCED");
                return 0;
            }
            stack[sp++] = c;
            continue;
        }

        /* Closing brackets – pop and compare */
        if (c == ')' || c == ']' || c == '}') {
            if (sp == 0) {                     /* nothing to match */
                puts("UNBALANCED");
                return 0;
            }
            char open = stack[--sp];
            if ((c == ')' && open != '(') ||
                (c == ']' && open != '[') ||
                (c == '}' && open != '{')) {
                puts("UNBALANCED");
                return 0;
            }
            continue;
        }

        /* All other characters are ignored */
    }

    /* After processing the whole string the stack must be empty */
    if (sp == 0)
        puts("BALANCED");
    else
        puts("UNBALANCED");

    return 0;
}
